import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { UserDto } from '../models/user';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class UserService {
  
   private apiUrl = `${environment.apiUrl}/user/`;

  constructor(private http: HttpClient) {}

  getUsers(): Observable<UserDto[]> {
    return this.http.get<UserDto[]>(`${this.apiUrl}`);
  }

  createUser(users: UserDto): Observable<UserDto> {
    return this.http.post<UserDto>(`${this.apiUrl}create-user`, users)
  }

  updateUserStatus(userId: number, status: string): Observable<UserDto> {
  return this.http.put<UserDto>(`${this.apiUrl}update-status/${userId}`, { status });
}

  deleteUser(userId: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}${userId}`);
  }
}
